    hit = float((ic_s > 0).mean()) if n else np.nan
    return {"ic": ic, "icir": icir, "ic_hit_ratio": hit, "n_ic_dates": n, "label": label}


def decay_analysis(factor_panel, close, horizons=(1, 3, 5, 10, 20), min_valid=8):
